import gql from 'graphql-tag';

export const GetTranslationsByPath = gql`
  query GetTranslationsByPath($featureAppTranslationsPath: String!) {
    featureAppTranslationsByPath(_path: $featureAppTranslationsPath) {
      item {
        ... on FeatureAppTranslationsModel {
          translations
        }
      }
    }
  }
`;

