import {StatusCode} from '@smart/platform-utils';
import {logger} from '@smart/website-lambda-utils';
import type {Client} from '@urql/core';
import type {AemPageModel} from './create-aem-page-model';
import {createAemPageModel} from './create-aem-page-model';
import {extractLanguage} from './extract-language';
import {getAemModelWithTranslationHelper} from './get-aem-model-with-translation';

export interface AemNotFoundResponse {
  readonly statusCode: StatusCode.NOT_FOUND;
  readonly aemPageModel?: AemPageModel;
}

export interface FetchAemNotFoundPageModelOptions {
  readonly client: Client;
  readonly query: string;
  readonly marketId: string;
  readonly pathname: string;
  readonly translationsQuery: string;
}

export async function fetchAemNotFoundPageModel({
  client,
  marketId,
  pathname,
  query,
  translationsQuery,
}: FetchAemNotFoundPageModelOptions): Promise<AemNotFoundResponse> {
  const language = extractLanguage(pathname);

  if (!language) {
    return {statusCode: StatusCode.NOT_FOUND};
  }

  const [data, error] = await getAemModelWithTranslationHelper({
    marketId,
    pathname: `/${language}/error-pages/404/index`,
    query,
    translationsQuery,
    client,
  });

  if (!data) {
    const graphQlErrors = error?.graphQLErrors ?? [];

    if (graphQlErrors.length === 0) {
      logger.debug(error);
    } else {
      for (const graphQLError of graphQlErrors) {
        logger.debug(graphQLError.message);
      }
    }
  }

  return {
    statusCode: StatusCode.NOT_FOUND,
    aemPageModel: data ? createAemPageModel(data) : undefined,
  };
}

