import path from 'path';
import {hreflangCountries} from '@smart/configs';
import type {
  GetPageByPathQuery,
  GetPageByPathQueryVariables,
  GetTranslationsByPathQuery,
  GetTranslationsByPathQueryVariables,
} from '@smart/website-graphql';
import {IdOperator} from '@smart/website-graphql';
import {aemWebsiteContentPath, logger} from '@smart/website-lambda-utils';
import type {Client, CombinedError} from '@urql/core';

type AemModelWithTranslationProps = {
  readonly marketId: string;
  readonly pathname: string;
  readonly hrefLangPathsFilter?: {_operator: IdOperator; value: string}[];
  readonly translationsQuery: string;
  readonly query: string;
  readonly client: Client;
  /**
   * @description for fetchAemNotFoundPageModel
   */
  readonly curLanguage?: string;
};

type AemModelWithTranslationResponse = [
  (GetPageByPathQuery & GetTranslationsByPathQuery) | undefined,
  CombinedError | undefined,
];
async function getAemModelWithTranslationHelper({
  marketId,
  pathname,
  hrefLangPathsFilter = [],
  client,
  translationsQuery,
  query,
  curLanguage,
}: AemModelWithTranslationProps): Promise<AemModelWithTranslationResponse> {
  const aemMarketPath = path.posix.join(aemWebsiteContentPath, marketId);
  const aemContentPath = path.posix.join(aemMarketPath, pathname);

  logger.debug(`Fetching AEM page content fragment for "${aemContentPath}".`);

  const hrefLangPageIdentifier =
    pathname === `/` ? `` : pathname.replace(/^\/[a-z]{2}\//i, ``);

  Object.keys(hreflangCountries).map((country) => {
    const languages =
      hreflangCountries[country as keyof typeof hreflangCountries];
    if (languages) {
      for (const language of languages) {
        hrefLangPathsFilter.push({
          _operator: IdOperator.Equals,
          value: `/content/dam/smart/website/${country.toLowerCase()}/${language.toLowerCase()}/${hrefLangPageIdentifier}index`,
        });
      }
    }
  });

  const currentLanguage =
    curLanguage ||
    pathname.split(`/`)[1] ||
    hreflangCountries[marketId as keyof typeof hreflangCountries]?.[0]!;

  const featureAppTranslationsPath = `/content/dam/smart/feature-apps/content/common/${marketId}/${currentLanguage.toLowerCase()}/translations`;

  // Use Promise.allSettled to ensure both requests are handled independently
  const data = await Promise.allSettled([
    client
      .query<
        GetPageByPathQuery & GetTranslationsByPathQuery,
        GetPageByPathQueryVariables
      >(query, {
        path: aemContentPath,
        marketPath: aemMarketPath.endsWith(`/`)
          ? aemMarketPath
          : `${aemMarketPath}/`,
        hrefLangPathsFilter,
      })
      .toPromise(),
    client
      .query<GetTranslationsByPathQuery, GetTranslationsByPathQueryVariables>(
        translationsQuery,
        {
          featureAppTranslationsPath,
        },
      )
      .toPromise(),
  ]);

  // Extract results and handle errors
  const [aemResult, translationsResult] = data;

  let aemData: (GetPageByPathQuery & GetTranslationsByPathQuery) | undefined;
  let aemError: CombinedError | undefined;
  let translationsData: GetTranslationsByPathQuery | undefined;

  if (aemResult.status === `fulfilled`) {
    aemData = aemResult.value.data;
    aemError = aemResult.value.error;
  } else {
    aemError = aemResult.reason;
  }

  if (translationsResult.status === `fulfilled`) {
    translationsData = translationsResult.value.data;
  }

  // Provide default value for translations if there was an error
  if (aemData && !translationsData) {
    aemData.featureAppTranslationsByPath = {item: {translations: {}}};
  } else if (aemData && translationsData) {
    aemData.featureAppTranslationsByPath =
      translationsData.featureAppTranslationsByPath;
  }

  return [aemData, aemError];
}

export {getAemModelWithTranslationHelper};

